```python
import itertools
import math

# We need to find factors of 240 such that 1 < c < b < a and a * b * c = 240
def find_factors(n):
    factors = []
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            a = i
            b = n // i
            factors.append((a, b))
    factors.append((1, n))
    f_factors = []
    for a, b in factors:
        if a*b < n:
            for c in range(2, b):
                if (a * b) % c == 0 and n % c == 0:
                    factors.append((a, b, c))
    return f_factors

# Get the factors of 240
factors_of_240 = find_factors(240)

# Find the tuple (a, b, c) with the largest value of b
max_b = 0
max_a_b_c = []

for f in factors_of_240:
    a, b, c = map(int, f)
    if 1 < c < b < a:
        if b > max_b:
            max_b = b
            max_a_b_c = (a, b, c)

print(max_b)
```

